/* Sharp Memory LCD LS013B7DH03 (128x128, 1 bit)
 * Bit-banged SPI, LSB first, SCS active HIGH.
 * VCOM is generated by toggling EXTCOMIN (EXTMODE = HIGH), ~1 Hz.
 *
 * All six pins must be configured in CubeMX as GPIO_Output.
 */
#include "main.h"
#include "sharp_lcd.h"

#define LCD_EXTMODE_PORT   GPIOA
#define LCD_EXTMODE_PIN    GPIO_PIN_4
#define LCD_SCK_PORT       GPIOA
#define LCD_SCK_PIN        GPIO_PIN_5
#define LCD_MOSI_PORT      GPIOA
#define LCD_MOSI_PIN       GPIO_PIN_7
#define LCD_CS_PORT        GPIOB
#define LCD_CS_PIN         GPIO_PIN_0
#define LCD_EXTCOMIN_PORT  GPIOB
#define LCD_EXTCOMIN_PIN   GPIO_PIN_1
#define LCD_DISP_PORT      GPIOB
#define LCD_DISP_PIN       GPIO_PIN_2

#define PIN_HIGH(n)   ((n##_PORT)->BSRR = (n##_PIN))
#define PIN_LOW(n)    ((n##_PORT)->BRR  = (n##_PIN))
#define PIN_TOGGLE(n) ((n##_PORT)->ODR ^= (n##_PIN))

/* Timing uses the DWT cycle counter, so it is independent of compiler
 * optimisation and core clock. Half an SCLK period is about 0.5 us plus
 * call overhead, which lands SCLK at roughly 0.6 - 0.8 MHz (limit: 1.1 MHz). */
#define HALF_CYCLES()  (SystemCoreClock / 2000000U)

static uint8_t fb[LCD_H][LCD_W / 8];
static uint8_t vcom_bit;     /* M1 bit, toggled on every command */
static uint8_t disp_on;

static void delay_cycles(uint32_t c) {
    uint32_t start = DWT->CYCCNT;
    while ((DWT->CYCCNT - start) < c) { }
}

static void delay_us(uint32_t us) {
    delay_cycles(us * (SystemCoreClock / 1000000U));
}

static void send_byte(uint8_t b) {
    uint32_t half = HALF_CYCLES();
    for (int i = 0; i < 8; i++) {          /* LSB first */
        if (b & 1) PIN_HIGH(LCD_MOSI); else PIN_LOW(LCD_MOSI);
        b >>= 1;
        delay_cycles(half);
        PIN_HIGH(LCD_SCK);                 /* latched on rising edge */
        delay_cycles(half);
        PIN_LOW(LCD_SCK);
    }
}

/* M2 = 1: clear all pixel memory (datasheet: initialise memory at power-up) */
static void clear_memory(void) {
    vcom_bit ^= 0x02;
    PIN_HIGH(LCD_CS);
    delay_us(10);
    send_byte(0x04 | vcom_bit);
    send_byte(0x00);
    delay_us(10);
    PIN_LOW(LCD_CS);
    delay_us(10);
}

void lcd_init(void) {
    CoreDebug->DEMCR |= CoreDebug_DEMCR_TRCENA_Msk;
    DWT->CYCCNT = 0;
    DWT->CTRL |= DWT_CTRL_CYCCNTENA_Msk;

    /* Power-up: SCS = SCLK = SI = L, DISP = L, EXTCOMIN toggling ~60 Hz */
    PIN_LOW(LCD_CS);
    PIN_LOW(LCD_SCK);
    PIN_LOW(LCD_MOSI);
    PIN_LOW(LCD_DISP);
    PIN_HIGH(LCD_EXTMODE);     /* VCOM from EXTCOMIN pin */
    PIN_LOW(LCD_EXTCOMIN);
    HAL_Delay(10);

    for (int i = 0; i < 12; i++) {
        PIN_TOGGLE(LCD_EXTCOMIN);
        HAL_Delay(8);          /* ~62 Hz */
    }

    clear_memory();
    lcd_clear();
    disp_on = 0;
}

/* Toggle EXTCOMIN at 1 Hz. Call from the main loop, never during a flush. */
void lcd_task(void) {
    static uint32_t last;
    uint32_t now = HAL_GetTick();
    if (now - last >= 500) {
        last = now;
        PIN_TOGGLE(LCD_EXTCOMIN);
    }
}

void lcd_clear(void) {
    for (int y = 0; y < LCD_H; y++)
        for (int x = 0; x < LCD_W / 8; x++)
            fb[y][x] = 0xFF;               /* 1 = white */
}

void lcd_set_pixel(int x, int y, int black) {
    if (x < 0 || x >= LCD_W || y < 0 || y >= LCD_H) return;
    if (black) fb[y][x >> 3] &= (uint8_t)~(1u << (x & 7));
    else       fb[y][x >> 3] |= (uint8_t)(1u << (x & 7));
}

void lcd_draw_circle(int cx, int cy, int r) {
    int x = r, y = 0, err = 1 - r;
    while (x >= y) {
        lcd_set_pixel(cx + x, cy + y, 1);
        lcd_set_pixel(cx - x, cy + y, 1);
        lcd_set_pixel(cx + x, cy - y, 1);
        lcd_set_pixel(cx - x, cy - y, 1);
        lcd_set_pixel(cx + y, cy + x, 1);
        lcd_set_pixel(cx - y, cy + x, 1);
        lcd_set_pixel(cx + y, cy - x, 1);
        lcd_set_pixel(cx - y, cy - x, 1);
        y++;
        if (err < 0) {
            err += 2 * y + 1;
        } else {
            x--;
            err += 2 * (y - x) + 1;
        }
    }
}

void lcd_fill_circle(int cx, int cy, int r) {
    for (int y = -r; y <= r; y++)
        for (int x = -r; x <= r; x++)
            if (x * x + y * y <= r * r)
                lcd_set_pixel(cx + x, cy + y, 1);
}

void lcd_flush(void) {
    vcom_bit ^= 0x02;

    PIN_HIGH(LCD_CS);
    delay_us(10);
    send_byte(0x01 | vcom_bit);            /* M0 = 1: write lines */
    for (int y = 0; y < LCD_H; y++) {
        send_byte((uint8_t)(y + 1));       /* line address, 1-based */
        for (int x = 0; x < LCD_W / 8; x++)
            send_byte(fb[y][x]);
        send_byte(0x00);                   /* line trailer */
    }
    send_byte(0x00);                       /* final trailer */
    delay_us(10);
    PIN_LOW(LCD_CS);

    if (!disp_on) {                        /* show memory only after it is written */
        delay_us(100);
        PIN_HIGH(LCD_DISP);
        disp_on = 1;
    }
}
